import React, { Suspense } from 'react';
import { Canvas, useLoader } from '@react-three/fiber';
import { OrbitControls, Stage } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader';
import * as THREE from 'three';

const Model: React.FC<{ path: string; format: 'obj' | 'fbx'; colors?: string[] }> = ({ path, format, colors }) => {
  const loader = format === 'fbx' ? FBXLoader : OBJLoader;
  const model = useLoader(loader, path);

  let materialIndex = 0;

  model.traverse((child) => {
    if ((child as THREE.Mesh).isMesh) {
      const mesh = child as THREE.Mesh;
      mesh.geometry?.computeVertexNormals?.();

      mesh.material = new THREE.MeshStandardMaterial({
        color: colors?.[materialIndex % (colors.length || 1)] ?? '#aaaaaa',
        roughness: 0.6,
        metalness: 0.3,
      });

      materialIndex++;
    }
  });

  return <primitive object={model} scale={0.5} />;
};

const ModelViewer: React.FC<{ path: string; format: 'obj' | 'fbx'; autoRotate?: boolean; colors?: string[] }> = ({
                                                                                                                   path,
                                                                                                                   format,
                                                                                                                   autoRotate = false,
                                                                                                                   colors,
                                                                                                                 }) => {
  return (
    <Canvas camera={{ position: [0, 2, 5], fov: 45 }} style={{ width: '100%', height: '300px' }}>

    <ambientLight />
      <pointLight position={[10, 10, 10]} />
      <Suspense fallback={null}>
        <Stage environment="city" intensity={1}>
          <Model path={path} format={format} colors={colors} />
        </Stage>
        <OrbitControls enableZoom={false} autoRotate={autoRotate} autoRotateSpeed={1.5} />
      </Suspense>
    </Canvas>
  );
};

export default ModelViewer;