import React, { useRef, useEffect } from "react";
import styled from "styled-components";

const SectionTitle = styled.h4`
    margin-top: 1.5rem;
    color: #9c27b0;
`;

const AudioList = styled.ul`
    list-style: none;
    padding: 0;
    margin: 0;
`;

const AudioItem = styled.li`
    margin-bottom: 1rem;
`;

const AudioLabel = styled.div`
    margin-bottom: 0.25rem;
    font-weight: bold;
    color: #fff;
`;

const VolumeAudio: React.FC<{ src: string; label: string; volume?: number }> = ({ src, label, volume = 1.0 }) => {
  const ref = useRef<HTMLAudioElement | null>(null);
  useEffect(() => {
    if (ref.current) ref.current.volume = volume;
  }, [volume]);

  return (
    <AudioItem>
      <AudioLabel>{label}{volume !== 1.0}</AudioLabel>
      <audio controls src={src} ref={ref} />
    </AudioItem>
  );
};

const AudioAssetsSection: React.FC = () => (
  <>
    <SectionTitle>Hastily Made Game Jam Music</SectionTitle>
    <AudioList>
      <VolumeAudio src="/assets/audio/Music/BGM.wav" label="BGM.wav" />
      <VolumeAudio src="/assets/audio/Music/Hack.wav" label="Hack.wav" volume={0.75} />
    </AudioList>

    <SectionTitle>Hastily Made Game Jam SFX</SectionTitle>
    <AudioList>
      <VolumeAudio src="/assets/audio/sfx/explosion.mp3" label="explosion.mp3" />
      <VolumeAudio src="/assets/audio/sfx/Fire.mp3" label="Fire.mp3" />
      <VolumeAudio src="/assets/audio/sfx/Giant%20eat%20sound.mp3" label="Giant eat sound.mp3" />
      <VolumeAudio src="/assets/audio/sfx/Giant%20punch%20sound.mp3" label="Giant punch sound.mp3" />
      <VolumeAudio src="/assets/audio/sfx/Giant%20take%20damage.mp3" label="Giant take damage.mp3" />
      <VolumeAudio src="/assets/audio/sfx/Keep%20damage.mp3" label="Keep damage.mp3" />
      <VolumeAudio src="/assets/audio/sfx/Monster%20Growl%201.mp3" label="Monster Growl 1.mp3" />
      <VolumeAudio src="/assets/audio/sfx/Monster%20Growl%202.mp3" label="Monster Growl 2.mp3" />
      <VolumeAudio src="/assets/audio/sfx/Monster%20Roar.mp3" label="Monster Roar.mp3" />
      <VolumeAudio src="/assets/audio/sfx/Power%20Down.mp3" label="Power Down.mp3" volume={0.5} />
    </AudioList>
  </>
);

export default AudioAssetsSection;
