import Tabs from "../reusable/Tabs";
import React from "react";
import styled from "styled-components";
import AudioAssetsSection from "./Audio";
import ThreeDAssetsSection from "./ThreeDassetsSection";
import VisualAssetsSection from "./VisualAssetsSection";

const AssetGrid = styled.div`
    display: grid;
    gap: 1rem;
    margin-bottom: 2rem;
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
`;

const AssetImage = styled.img`
    width: 100%;
    height: auto;
    border: 1px solid #ccc;
    border-radius: 5px;
    object-fit: contain;
`;

const MyAssetShowcase: React.FC = () => {
  const assetTabs = [
    { id: "2D", label: "2D Art", content: <VisualAssetsSection /> },
    { id: "3D", label: "3D Models", content: <ThreeDAssetsSection /> },
    { id: "Audio", label: "Audio", content: <AudioAssetsSection /> },
  ];

  return <Tabs tabs={assetTabs} tabCategory="Assets" />;
};

export default MyAssetShowcase;
