import React from "react";
import styled from "styled-components";

const SectionTitle = styled.h4`
  margin-top: 1.5rem;
  color: #9c27b0;
`;

const AssetGrid = styled.div`
  display: grid;
  gap: 1rem;
  margin-bottom: 2rem;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
`;

const AssetImage = styled.img`
  width: 100%;
  height: auto;
  border: 1px solid #ccc;
  border-radius: 5px;
  object-fit: contain;
`;

const VisualAssetsSection: React.FC = () => (
  <>
    <SectionTitle>Inventory Icons (Procreate, GIMP)</SectionTitle>
    <AssetGrid>
      <AssetImage src="/assets/icons/cooked%20egg.png" />
      <AssetImage src="/assets/icons/Egg.png" />
      <AssetImage src="/assets/icons/Hoe.png" />
      <AssetImage src="/assets/icons/Scythe.png" />
      <AssetImage src="/assets/icons/Milk.png" />
      <AssetImage src="/assets/icons/StoveItem.png" />
    </AssetGrid>

    <SectionTitle>NPC Sprites</SectionTitle>
    <AssetGrid>
      <AssetImage src="/assets/sprites/Coal.png" />
      <AssetImage src="/assets/sprites/Iron%20Ore.png" />
      <AssetImage src="/assets/sprites/Copper%20Ore.png" />
    </AssetGrid>

    <SectionTitle>Textures</SectionTitle>
    <AssetGrid>
      <AssetImage src="/assets/textures/Flames.png" />
      <AssetImage src="/assets/textures/Sci%20Fi%20Flooring.png" />
      <AssetImage src="/assets/textures/Electric.png" />
    </AssetGrid>

    <SectionTitle>Tiles</SectionTitle>
    <AssetGrid>
      <AssetImage src="/assets/tiles/Grass_1.png" />
      <AssetImage src="/assets/tiles/BROC_Grass_1.png" />
      <AssetImage src="/assets/tiles/BottomRightGrass_1.png" />
      <AssetImage src="/assets/tiles/Grass_LeftEdge.png" />
      <AssetImage src="/assets/tiles/StoneyGrass_MakeConvexBottomLeftCorner.png" />
    </AssetGrid>
  </>
);

export default VisualAssetsSection;
