import React, { useState } from "react";
import styled from "styled-components";
import ModelViewer from "./ModelViewer";

const SectionTitle = styled.h4`
    margin-top: 1.5rem;
    color: #9c27b0;
`;

const AssetGrid = styled.div`
    display: grid;
    gap: 1rem;
    margin-bottom: 2rem;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
`;

const ColorControls = styled.div`
    display: flex;
    gap: 1rem;
    margin-bottom: 1rem;

    label {
        color: #fff;
        display: flex;
        flex-direction: column;
        font-size: 0.9rem;
    }

    input[type="color"] {
        margin-top: 0.25rem;
        width: 40px;
        height: 25px;
        border: none;
        cursor: pointer;
    }
`;

const ThreeDAssetsSection: React.FC = () => {
  const [colors, setColors] = useState<string[]>(['#9c27b0', '#4dd0e1', '#000']);

  return (
    <>
      <SectionTitle>Low-poly Props (Blender)</SectionTitle>
      <ColorControls>
        {colors.map((color, i) => (
          <label key={i}>
            Color {i + 1}
            <input
              type="color"
              value={color}
              onChange={(e) => {
                const newColors = [...colors];
                newColors[i] = e.target.value;
                setColors(newColors);
              }}
            />
          </label>
        ))}
      </ColorControls>
      <AssetGrid>
        <ModelViewer path="/assets/3d/turret_barrel.obj" format="obj" autoRotate colors={colors} />
        <ModelViewer path="/assets/3d/BarricadeModel_1.fbx" format="fbx" autoRotate colors={colors} />
        <ModelViewer path="/assets/3d/ProjectileAmmoModel_1.fbx" format="fbx" autoRotate colors={colors} />
        <ModelViewer path="/assets/3d/Sprayer.fbx" format="fbx" autoRotate colors={colors} />
        <ModelViewer path="/assets/3d/TargetingSystemModel_1.fbx" format="fbx" autoRotate colors={colors} />
        <ModelViewer path="/assets/3d/TowerBase_1.fbx" format="fbx" autoRotate colors={colors} />
        <ModelViewer path="/assets/3d/WeaponMount.fbx" format="fbx" autoRotate colors={colors} />
        <ModelViewer path="/assets/3d/WeaponMountModel_1.fbx" format="fbx" autoRotate colors={colors} />
        <ModelViewer path="/assets/3d/WeaponMountModel_2.fbx" format="fbx" autoRotate colors={colors} />
      </AssetGrid>
    </>
  );
};

export default ThreeDAssetsSection;
